def __post_init__(self) -> None:
    """Discard provider-controlled text before the failure can become observable."""
    if self.status_code is not None and 400 <= self.status_code < 500:
        safe_message = f"Provider request failed with status code {self.status_code}: {self.message}"
    elif self.status_code is not None:
        safe_message = f"Provider request failed with status code {self.status_code}."
    else:
        safe_message = "Provider request failed."
    object.__setattr__(self, "message", safe_message)
